package com.minimarket.producto.service.impl; import com.minimarket.common.exception.*; import com.minimarket.producto.dto.*; import com.minimarket.producto.entity.UnidadMedida; import com.minimarket.producto.repository.UnidadMedidaRepository; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class UnidadMedidaServiceImpl implements com.minimarket.producto.service.UnidadMedidaService{private final UnidadMedidaRepository r;public Page<UnidadMedidaResponseDTO> listar(Pageable p){return r.findAll(p).map(this::d);}public UnidadMedidaResponseDTO obtener(Long id){return d(f(id));}@Transactional public UnidadMedidaResponseDTO crear(UnidadMedidaRequestDTO x){if(r.findByNombreIgnoreCase(x.nombre()).isPresent()||r.findByAbreviaturaIgnoreCase(x.abreviatura()).isPresent())throw new BusinessException("Nombre o abreviatura de unidad ya existe");return d(r.save(UnidadMedida.builder().nombre(x.nombre().trim()).abreviatura(x.abreviatura().trim()).build()));}@Transactional public UnidadMedidaResponseDTO actualizar(Long id,UnidadMedidaRequestDTO x){UnidadMedida u=f(id);r.findByNombreIgnoreCase(x.nombre()).filter(a->!a.getId().equals(id)).ifPresent(a->{throw new BusinessException("Nombre ya existe");});r.findByAbreviaturaIgnoreCase(x.abreviatura()).filter(a->!a.getId().equals(id)).ifPresent(a->{throw new BusinessException("Abreviatura ya existe");});u.setNombre(x.nombre().trim());u.setAbreviatura(x.abreviatura().trim());return d(u);}private UnidadMedida f(Long id){return r.findById(id).orElseThrow(()->ResourceNotFoundException.of("UnidadMedida",id));}private UnidadMedidaResponseDTO d(UnidadMedida u){return new UnidadMedidaResponseDTO(u.getId(),u.getNombre(),u.getAbreviatura(),u.getCreatedAt());}}